function get_abbrev(s)
{	# return abbrev from ``key = abbrev,''
	sub(/^[^=]*= */,"",s)	# discard text up to start of non-blank value
	sub(/ *,? *$/,"",s)	# discard trailing optional whitspace, quote,
				# optional comma, and optional space
	return (s)
}


function get_key(s)
{	# return kay from ``key = "value",''
	sub(/^ */,"",s)		# discard leading space
	sub(/ *=.*$/,"",s)	# discard everthing after key

	return (s)
}


function get_value(s)
{	# return value from ``key = "value",''
	sub(/^[^\"]*\" */,"",s)	# discard text up to start of non-blank value
	sub(/ *\",? *$/,"",s)	# discard trailing optional whitspace, quote,
				# optional comma, and optional space
	return (s)
}


function html_accents(s)
{
	if (index(s,"\\") > 0)			# important optimization
	{
		# Convert common lower-case accented letters according to the
		# table on p. 169 of in Peter Flynn's ``The World Wide Web
		# Handbook'', International Thomson Computer Press, 1995, ISBN
		# 1-85032-205-8.  The official table of ISO Latin 1 SGML
		# entities used in HTML can be found in the file
		# /usr/local/lib/html-check/lib/ISOlat1.sgml (your path
		# may differ).

		gsub(/{\\\a}/,	"\\&agrave;",	s)
		gsub(/{\\'a}/,	"\\&aacute;",	s)
		gsub(/{\\[\^]a}/,"\\&acirc;",	s)
		gsub(/{\\~a}/,	"\\&atilde;",	s)
		gsub(/{\\\"a}/,	"\\&auml;",	s)
		gsub(/{\\aa}/,	"\\&aring;",	s)
		gsub(/{\\ae}/,	"\\&aelig;",	s)

		gsub(/\{\\c\{c\}\}/,"\\&ccedil;",	s)

		gsub(/\{\\\e\}/,	"\\&egrave;",	s)
		gsub(/\{\\'e\}/,	"\\&eacute;",	s)
		gsub(/\{\\[\^]e\}/,"\\&ecirc;",	s)
		gsub(/\{\\\"e\}/,	"\\&euml;",	s)

		gsub(/\{\\\i\}/,	"\\&igrave;",	s)
		gsub(/\{\\'i\}/,	"\\&iacute;",	s)
		gsub(/\{\\[\^]i\}/,"\\&icirc;",	s)
		gsub(/\{\\\"i\}/,	"\\&iuml;",	s)

		# ignore eth and thorn

		gsub(/\{\\~n\}/,	"\\&ntilde;",	s)

		gsub(/\{\\\o\}/,	"\\&ograve;",	s)
		gsub(/\{\\'o\}/,	"\\&oacute;",	s)
		gsub(/\{\\[\^]o\}/, "\\&ocirc;",	s)
		gsub(/\{\\~o\}/,	"\\&otilde;",	s)
		gsub(/\{\\\"o\}/,	"\\&ouml;",	s)
		gsub(/\{\\o\}/,	"\\&oslash;",	s)

		gsub(/\{\\\u\}/,	"\\&ugrave;",	s)
		gsub(/\{\\'u\}/,	"\\&uacute;",	s)
		gsub(/\{\\[\^]u\}/,"\\&ucirc;",	s)
		gsub(/\{\\\"u\}/,	"\\&uuml;",	s)

		gsub(/\{\\'y\}/,	"\\&yacute;",	s)
		gsub(/\{\\\"y\}/,	"\\&yuml;",	s)

		# Now do the same for upper-case accents

		gsub(/\{\\\A\}/,	"\\&Agrave;",	s)
		gsub(/\{\\'A\}/,	"\\&Aacute;",	s)
		gsub(/\{\\[\^]A\}/,	"\\&Acirc;",	s)
		gsub(/\{\\~A\}/,	"\\&Atilde;",	s)
		gsub(/\{\\\"A\}/,	"\\&Auml;",	s)
		gsub(/\{\\AA\}/,	"\\&Aring;",	s)
		gsub(/\{\\AE\}/,	"\\&AElig;",	s)

		gsub(/\{\\c\{C\}\}/,"\\&Ccedil;",	s)

		gsub(/\{\\\e\}/,	"\\&Egrave;",	s)
		gsub(/\{\\'E\}/,	"\\&Eacute;",	s)
		gsub(/\{\\[\^]E\}/,	"\\&Ecirc;",	s)
		gsub(/\{\\\"E\}/,	"\\&Euml;",	s)

		gsub(/\{\\\I\}/,	"\\&Igrave;",	s)
		gsub(/\{\\'I\}/,	"\\&Iacute;",	s)
		gsub(/\{\\[\^]I\}/,	"\\&Icirc;",	s)
		gsub(/\{\\\"I\}/,	"\\&Iuml;",	s)

		# ignore eth and thorn

		gsub(/\{\\~N\}/,	"\\&Ntilde;",	s)

		gsub(/\{\\\O\}/,	"\\&Ograve;",	s)
		gsub(/\{\\'O\}/,	"\\&Oacute;",	s)
		gsub(/\{\\[\^]O\}/,	"\\&Ocirc;",	s)
		gsub(/\{\\~O\}/,	"\\&Otilde;",	s)
		gsub(/\{\\\"O\}/,	"\\&Ouml;",	s)
		gsub(/\{\\O\}/,	"\\&Oslash;",	s)

		gsub(/\{\\\U\}/,	"\\&Ugrave;",	s)
		gsub(/\{\\'U\}/,	"\\&Uacute;",	s)
		gsub(/\{\\[\^]U\}/,	"\\&Ucirc;",	s)
		gsub(/\{\\\"U\}/,	"\\&Uuml;",	s)

		gsub(/\{\\'Y\}/,	"\\&Yacute;",	s)

		gsub(/\{\\ss\}/,	"\\&szlig;",	s)

		# Others not mentioned in Flynn's book
		gsub(/\{\\'\\i\}/,"\\&iacute;",	s)
		gsub(/\{\\'\\j\}/,"j",		s)
	}
	return (s)
}


